structlogger = structlog.get_logger()

_SAFE_DEPLOYMENT_ID = re.compile(r"^[a-zA-Z0-9_-]+$")


class AllBotsRecentlyActiveError(Exception):
    """Raised when no running bot has been inactive long enough to be evicted."""


INSPECTOR_CHANNEL_NAME = "inspector"

INSPECTOR_CHANNEL_NOT_CONFIGURED_ERROR = (
    "Inspector channel not configured in integrations.yml or credentials.yml"
)


class BotSessionStatus(str, Enum):
    """Enum for the bot status."""

    QUEUED = "queued"
    RUNNING = "running"
    STOPPED = "stopped"


class BotSession(BaseModel):
    """Store information about a running bot."""

    model_config = ConfigDict(arbitrary_types_allowed=True)

    deployment_id: str
    status: BotSessionStatus
    process: subprocess.Popen
    url: str
    internal_url: str
    port: int
    log_id: str
    returncode: Optional[int] = None
    last_active_at: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    error: Optional[str] = None

    def is_alive(self) -> bool:
        """Check if the bot is alive."""
        return self.process.poll() is None

    def is_status_indicating_alive(self) -> bool:
        """Check if the status indicates that the bot is alive."""
        return self.status in {BotSessionStatus.QUEUED, BotSessionStatus.RUNNING}

    def has_died_recently(self) -> bool:
        """Check if the bot has died recently.

        Process will indicate that the bot exited,
        but status is not yet updated.
        """
        return self.is_status_indicating_alive() and not self.is_alive()

    async def completed_startup_recently(self) -> bool:
        """Check if the bot has completed startup recently."""
        return self.status == BotSessionStatus.QUEUED and await is_bot_startup_finished(
            self
        )


def bot_path(deployment_id: str) -> str:
    """Return the path to the bot directory for a given deployment id.

    Raises ValueError if deployment_id contains characters other than
    alphanumerics, hyphens, or underscores, preventing path traversal.
    """
    if not _SAFE_DEPLOYMENT_ID.match(deployment_id):
        raise ValueError(f"Invalid deployment_id: {deployment_id!r}")
    bots_dir = os.path.abspath(f"{config.SERVER_BASE_WORKING_DIRECTORY}/bots")
    return subpath(bots_dir, deployment_id)


def _load_yaml_mapping(path: str) -> Optional[Dict[str, Any]]:
    """Load a root-level YAML mapping, or return None if there is none.

    The file is loaded without environment-variable expansion so that unrelated,
    unset ``${...}`` references elsewhere in it (e.g. another channel's token)
    don't turn a presence-only check into a parse error.
    """
    if not os.path.isfile(path):
        return None

    yaml = YAML(typ="safe", pure=True)
    with open(path, encoding="utf-8") as yaml_file:
        content = yaml.load(yaml_file)

    return content if isinstance(content, dict) else None


def _is_channel_enabled(channel_config: Any) -> bool:
    """Return whether a Mantle ``channels:`` entry is switched on.

    Mirrors :func:`rasa.mantle.config.channels.parse_channels`: an entry counts
    as enabled unless it explicitly says ``enabled: false``, so ``inspector:``,
    ``inspector: {}`` and ``inspector: {enabled: true}`` all pass. Only a
    mapping can carry the flag; anything else is left to the stricter parser
    that runs at bot startup.
    """
    if not isinstance(channel_config, Mapping):
        return True

    return channel_config.get(ENABLED_KEY, True) is not False


def has_inspector_channel_configured(bot_base_path: str) -> bool:
    """Return whether the assistant declares an inspector input channel.

    Both project layouts are accepted, since the model manager serves v1 and
    Mantle assistants side by side:

    - Mantle: ``inspector`` under the ``channels`` key of ``integrations.yml``,
      unless it is switched off with ``enabled: false``.
    - CALM v1: a top-level ``inspector`` key in ``credentials.yml``.

    Either file satisfying the check is enough, deliberately looser than
    ``resolve_channels_config``, which uses
    :func:`~rasa.shared.engine_version.is_mantle_cli_context`: a two-of-three
    Mantle layout, or a Mantle archive beside ``integrations.yml`` when
    ``skills/`` is absent. Deployed bot directories are assembled from a
    ``/bot`` payload that need not carry ``skills/``, so this check reads
    ``integrations.yml`` directly.
    """
    integrations = _load_yaml_mapping(subpath(bot_base_path, MANTLE_INTEGRATIONS_FILE))
    if integrations is not None:
        channels = integrations.get(CHANNELS_KEY)
        if isinstance(channels, dict) and INSPECTOR_CHANNEL_NAME in channels:
            return _is_channel_enabled(channels[INSPECTOR_CHANNEL_NAME])

    credentials = _load_yaml_mapping(subpath(bot_base_path, DEFAULT_CREDENTIALS_PATH))
    return credentials is not None and INSPECTOR_CHANNEL_NAME in credentials


def inspector_socketio_path(bot_base_path: str) -> str:
    """Return the Socket.IO path the agent's inspector channel listens on.

    Operators may override ``socketio_path`` per channel, so the bridge cannot
    assume the shipped default. Falls back to it whenever the agent does not
    say otherwise, which is the common case.
    """
    credentials = _load_yaml_mapping(subpath(bot_base_path, DEFAULT_CREDENTIALS_PATH))
    inspector = (credentials or {}).get(INSPECTOR_CHANNEL_NAME)
    if not isinstance(inspector, dict):
        return INSPECTOR_SOCKETIO_PATH

    return inspector.get("socketio_path") or INSPECTOR_SOCKETIO_PATH


def has_model_server_configured(bot_base_path: str) -> bool:
    """Return whether endpoints.yml defines a `models` (model server) entry.

    A `models` entry configures Rasa's model-server polling mechanism, which
    swaps the running agent's model on a background schedule independently of
    the model manager's own train/deploy/evict lifecycle. It is not supported
    for bots managed by the model manager.
    """
    endpoints = _load_yaml_mapping(subpath(bot_base_path, "endpoints.yml"))
    return endpoints is not None and "models" in endpoints


def check_inspector_channel_configuration(bot: BotSession) -> None:
    """Record a deployment error when the inspector channel is unavailable."""
    if has_inspector_channel_configured(bot_path(bot.deployment_id)):
        bot.error = None
    else:
        bot.error = INSPECTOR_CHANNEL_NOT_CONFIGURED_ERROR


async def is_bot_startup_finished(bot: BotSession) -> bool:
    """Send a request to the bot to see if the bot is up and running."""
    health_timeout = aiohttp.ClientTimeout(total=5, sock_connect=2, sock_read=3)
    try:
        async with aiohttp.ClientSession(timeout=health_timeout) as session:
            # can't use /status as by default the bot API is not enabled, only
            # the input channel
            async with session.get(f"{bot.internal_url}/license") as resp:
                return resp.status == 200
    except aiohttp.client_exceptions.ClientConnectorError:
        return False


def set_bot_status_to_stopped(bot: BotSession) -> None:
    """Set a bots state to stopped."""
    structlogger.info(
        "model_runner.bot_stopped",
        deployment_id=bot.deployment_id,
        status=bot.process.returncode,
    )
    bot.status = BotSessionStatus.STOPPED
    bot.returncode = bot.process.returncode


def set_bot_status_to_running(bot: BotSession) -> None:
    """Set a bots state to running."""
    structlogger.info(
        "model_runner.bot_running",
        deployment_id=bot.deployment_id,
    )
    bot.status = BotSessionStatus.RUNNING
    bot.last_active_at = datetime.now(timezone.utc)


def get_open_port() -> int:
    """Get an open port on the system that is not in use yet."""
    # from https://stackoverflow.com/questions/2838244/get-open-tcp-port-in-python/2838309#2838309
    import socket

    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.bind(("", 0))
    s.listen(1)
    port = s.getsockname()[1]
    s.close()
    return port


def prepare_bot_directory(
    bot_base_path: str,
    model_name: str,
    raw_configs: Dict[str, bytes],
) -> None:
    """Prepare the bot directory for a new bot session."""
    if not os.path.exists(bot_base_path):
        os.makedirs(bot_base_path, exist_ok=True)
    else:
        shutil.rmtree(bot_base_path, ignore_errors=True)

    model_file_name = f"{model_name}.{MODEL_ARCHIVE_EXTENSION}"
    model_path = subpath(models_base_path(), model_file_name)

    if config.SERVER_MODEL_REMOTE_STORAGE and not os.path.exists(model_path):
        fetch_remote_model_to_dir(
            model_file_name,
            models_base_path(),
            config.SERVER_MODEL_REMOTE_STORAGE,
        )

    if not os.path.exists(model_path):
        raise ModelNotFound(f"Model '{model_file_name}' not found in '{model_path}'.")

    os.makedirs(subpath(bot_base_path, "models"), exist_ok=True)
    shutil.copy(
        src=model_path,
        dst=subpath(bot_base_path, "models"),
    )

    write_project_tree_files(raw_configs, bot_base_path)


def fetch_remote_model_to_dir(
    model_name: str, target_path: str, storage_type: str
) -> str:
    """Fetch the model from remote storage.

    Returns the path to the model directory.
    """
    from rasa.core.persistor import get_persistor

    persistor = get_persistor(storage_type)

    # we know there must be a persistor, because the config is set
    # this is here to please the type checker for the call below
    assert persistor is not None

    try:
        return persistor.retrieve(model_name=model_name, target_path=target_path)
    except FileNotFoundError as e:
        raise ModelNotFound("Model not found") from e


def fetch_size_of_remote_model(
    model_name: str, storage_type: str, model_path: str
) -> int:
    """Fetch the size of the model from remote storage."""
    from rasa.core.persistor import get_persistor

    persistor = get_persistor(storage_type)

    # we now there must be a persistor, because the config is set
    # this is here to please the type checker for the call below
    assert persistor is not None

    return persistor.size_of_persisted_model(
        model_name=model_name, target_path=model_path
    )


def start_bot_process(
    deployment_id: str, bot_base_path: str, base_url_path: str
) -> BotSession:
    port = get_open_port()

    # No channel-config flag is passed: `rasa run` has no `--integrations`
    # option. The process runs with `cwd=bot_base_path`, so channel loading
    # resolves `integrations.yml` (Mantle) or `credentials.yml` (CALM v1) from
    # the bot directory itself. Mantle rejects `--endpoints` even when that
    # file is missing, so the flag is passed only for CALM.
    model_path = f"{bot_base_path}/models"
    arguments = ["run"]
    if not is_mantle_cli_context(project_root=bot_base_path, model_path=model_path):
        arguments.extend(["--endpoints", f"{bot_base_path}/endpoints.yml"])
    arguments.extend(
        [
            "--debug",
            "--enable-api",
            f"--port={port}",
            "--model",
            model_path,
        ]
    )

    structlogger.debug(
        "model_runner.bot.starting_command",
        deployment_id=deployment_id,
        arguments=" ".join(arguments),
    )

    warm_process = start_rasa_process(cwd=bot_base_path, arguments=arguments)

    internal_bot_url = f"http://localhost:{port}"

    structlogger.info(
        "model_runner.bot.starting",
        deployment_id=deployment_id,
        log=logs_path(warm_process.log_id),
        url=internal_bot_url,
        port=port,
        pid=warm_process.process.pid,
    )

    return BotSession(
        deployment_id=deployment_id,
        status=BotSessionStatus.QUEUED,
        process=warm_process.process,
        url=f"{base_url_path}?deployment_id={deployment_id}",
        internal_url=internal_bot_url,
        port=port,
        log_id=warm_process.log_id,
    )


def decode_bot_configs(
    encoded_configs: Mapping[str, Union[str, Dict[str, str]]],
) -> Dict[str, bytes]:
    """Decode base64-encoded bot config files to raw bytes."""
    return {
        k: base64.b64decode(v)
        for k, v in encoded_configs.items()
        if k in SHORT_CONFIG_KEYS and isinstance(v, str)
    }


def run_bot(
    deployment_id: str,
    model_name: str,
    base_url_path: str,
    encoded_configs: Mapping[str, Union[str, Dict[str, str]]],
) -> BotSession:
    """Deploy a bot based on a given training id."""
    with structlog.contextvars.bound_contextvars(model_name=model_name):
        bot_base_path = bot_path(deployment_id)
        prepare_bot_directory(
            bot_base_path, model_name, decode_bot_configs(encoded_configs)
        )
        prompts = encoded_configs.get("prompts")
        if isinstance(prompts, dict):
            handle_prompts(prompts, Path(bot_base_path))
        return start_bot_process(deployment_id, bot_base_path, base_url_path)


def write_project_tree_files(raw_configs: Dict[str, bytes], base_path: str) -> None:
    """Write assistant files into the bot working directory.

    Short keys (``config`` / ``credentials`` / ``integrations`` / ``endpoints``)
    map to hardcoded YAML filenames. Every other key is treated as a relative
    path under ``base_path``.

    Security: relative path keys are validated via
    ``validate_relative_bot_path`` + ``subpath()`` to prevent directory
    traversal.
    """
    for key, content in raw_configs.items():
        if key in SHORT_CONFIG_KEYS:
            if not content:
                continue
            target = subpath(base_path, SHORT_CONFIG_FILES[key])
        else:
            validate_relative_bot_path(key)
            target = subpath(base_path, key)
        os.makedirs(os.path.dirname(target), exist_ok=True)
        with open(target, "wb") as f:
            f.write(content)


def run_bot_from_raw_configs(
    deployment_id: str,
    model_name: str,
    base_url_path: str,
    raw_configs: Dict[str, bytes],
) -> BotSession:
    """Deploy a bot using raw (unencoded) config files from a training zip."""
    with structlog.contextvars.bound_contextvars(model_name=model_name):
        bot_base_path = bot_path(deployment_id)
        prepare_bot_directory(bot_base_path, model_name, raw_configs)
        return start_bot_process(deployment_id, bot_base_path, base_url_path)


async def update_bot_status(bot: BotSession) -> None:
    """Update the status of a bot based on the process return code."""
    try:
        if bot.has_died_recently():
            set_bot_status_to_stopped(bot)
        elif await bot.completed_startup_recently():
            set_bot_status_to_running(bot)
            check_inspector_channel_configuration(bot)
    except Exception as e:
        structlogger.error("model_runner.update_bot_status.error", error=str(e))


def terminate_bot(bot: BotSession) -> None:
    """Terminate the bot process."""
    if not bot.is_status_indicating_alive():
        # if the bot is not running, we don't need to terminate it
        return

    try:
        bot.process.terminate()
        structlogger.info(
            "model_runner.stop_bot.stopped",
            deployment_id=bot.deployment_id,
            status=bot.process.returncode,
        )
        bot.status = BotSessionStatus.STOPPED
        bot.returncode = bot.process.returncode
    except ProcessLookupError:
        structlogger.debug(
            "model_runner.stop_bot.process_not_found",
            deployment_id=bot.deployment_id,
        )


def evict_oldest_inactive_bot(running_bots: Dict[str, "BotSession"]) -> None:
    """Terminate the least recently active running bot if inactive long enough.

    Only bots in RUNNING status are eviction candidates; QUEUED bots are excluded
    because they have not yet had a chance to serve traffic.

    Args:
        running_bots: The current mapping of deployment IDs to bot sessions.

    Raises:
        AllBotsRecentlyActiveError: If no running bot has been inactive for at
            least the configured minimum inactive time.
    """
    min_inactive_before_eviction = timedelta(
        milliseconds=config.MODEL_INACTIVE_AFTER_MS
    )
    candidates = [
        bot for bot in running_bots.values() if bot.status == BotSessionStatus.RUNNING
    ]
    if not candidates:
        raise AllBotsRecentlyActiveError("No running bots are available for eviction.")

    oldest = min(candidates, key=lambda bot: bot.last_active_at)
    if (
        datetime.now(timezone.utc) - oldest.last_active_at
        < min_inactive_before_eviction
    ):
        raise AllBotsRecentlyActiveError(
            f"All running bots have been active within the last "
            f"{min_inactive_before_eviction}."
        )

    terminate_bot(oldest)
    structlogger.info(
        "model_runner.bot_evicted",
        deployment_id=oldest.deployment_id,
        last_active_at=oldest.last_active_at.isoformat(),
    )
